"use strict";
/* ================= QUESTION BANK =================
   Each: t=topic, q=question, a=[correct, wrong, wrong], h=hint, e=why, s=visual (optional),
   who="adult"|"minor" when a rule only applies to one age group (omitted = everyone).
   Based on the California Driver's Handbook and Vehicle Code, including laws in effect in 2026. */
const TOPICS = {
  signs:  {name:"Signs & Signals", icon:"octagon"},
  speed:  {name:"Speed Limits", icon:"speed"},
  row:    {name:"Right-of-Way", icon:"yield"},
  lanes:  {name:"Lanes, Turns & Passing", icon:"ico-lanes"},
  parking:{name:"Parking", icon:"ico-parking"},
  share:  {name:"Sharing the Road", icon:"bike"},
  safe:   {name:"Safe Driving Skills", icon:"diamond"},
  dui:    {name:"Alcohol & Drugs", icon:"nodrink"},
  license:{name:"Licenses & Insurance", icon:"permit"},
  freeway:{name:"Freeways", icon:"merge"},
  rail:   {name:"Railroads & School Buses", icon:"rxr"},
  emerg:  {name:"Emergencies & Crashes", icon:"ico-hazard"}
};

const TIPS = {
  signs:{tips:["Learn shapes first — you can name many signs before you can read them.","Octagon = STOP, triangle = YIELD, pentagon = SCHOOL, circle = RAILROAD, diamond = WARNING.","Colors: red = stop or not allowed, yellow = warning, orange = road work, green = directions, blue = services.","Flashing red = treat it like a stop sign. Flashing yellow = slow down and go carefully. Dark signal = four-way stop.","Green arrow = protected turn. Flashing yellow arrow = you may turn, but yield first. Red arrow = no turning."],trick:"Count the sides: 8 = STOP, 5 = SCHOOL, 3 = YIELD. Round = Railroad (both start with R)."},
  speed:{tips:["Max on most CA highways is 65 mph (70 only where posted). Two-lane undivided road = 55 unless posted.","Towing a trailer = 55 mph, in the right lane or a truck lane.","25 mph: residential and business districts, near schools when kids are present, senior zones. More cities now post 20 mph school zones (AB 382) — obey the sign.","15 mph: alleys, blind intersections, and railroad crossings where you can't see 400 ft both ways.","Wet road: slow 5–10 mph. Packed snow: cut speed in half. Ice: 5 mph or less.","The Basic Speed Law beats every number: never go faster than is safe for conditions."],trick:"\"15 for tight spots, 25 for neighborhoods, 55 and 65 for open roads.\""},
  row:{tips:["Four-way stop: whoever stops first goes first. Tie? The car on the RIGHT goes first.","Turning left? Yield to oncoming traffic.","T-intersection with no signs: the through road has the right-of-way.","Every corner has a crosswalk, painted or not. Blind pedestrians (white cane or guide dog) always go first — don't honk.","Right-of-way is something you GIVE, never something you take."],trick:"\"Right goes first, left waits.\" Tie at a stop sign → right side wins. Turning left → you wait."},
  lanes:{tips:["Signal 100 feet before a turn, and at least 5 seconds before changing lanes on the freeway.","Center two-way left-turn lane: 200 feet max. Bike lane before a right turn: enter within 200 feet.","Double solid yellow = no passing (you may cross it to turn left into a driveway). Double solid white = never cross.","Back to your lane after passing when you can see the car's headlights in your rearview mirror.","U-turns: never on a one-way street, and never where you can't see 200 feet each way."],trick:"Hand signals: arm straight out = LEFT, arm bent up = RIGHT, arm bent down = SLOW/STOP."},
  parking:{tips:["Distances: 15 ft from a fire hydrant, 20 ft from a crosswalk, 3 ft from a wheelchair ramp, 7½ ft from railroad tracks, within 18 inches of the curb.","Downhill: wheels TOWARD the curb. Uphill: wheels AWAY from the curb. No curb: wheels toward the edge of the road.","Curbs: Red = no stopping. White = quick passenger or mail stop. Green = time limit. Yellow = loading. Blue = disabled placard only.","Never park in a tunnel, on a crosswalk, or double-park."],trick:"Uphill = Up and away. Curbs: White = Wait briefly, Green = Go-time limit, Red = Restricted."},
  share:{tips:["Passing a bike: change lanes if one is open (law since 2023); otherwise give at least 3 feet.","Siren behind you? Pull to the right edge and STOP. In an intersection? Drive through it first. Stay 300+ feet behind.","Slow Down, Move Over: for emergency vehicles, tow trucks, Caltrans — and since 2026, ANY stopped vehicle with hazard lights flashing.","Big trucks have huge blind spots ('No Zones'). If you can't see the driver in their mirror, they can't see you.","Lane splitting by motorcycles is legal in CA. Give motorcycles a full lane."],trick:"\"3 feet for bikes, 300 feet behind sirens.\""},
  safe:{tips:["Keep a 3-second following distance — more in rain, behind motorcycles, or when tailgated.","Look 10–15 seconds ahead. Check blind spots by turning your head.","Headlights: 30 min after sunset to 30 min before sunrise, when you can't see 1,000 ft, or when your wipers are on.","Dim high beams within 500 ft of oncoming cars and 300 ft behind a car you're following.","Skidding? Ease off the gas and steer where you WANT to go. First rain = slickest roads.","Phones: drivers 18+ may only use one hands-free and mounted, with a single tap or swipe."],trick:"\"3 seconds back, 10–15 seconds ahead.\" High beams: 500 oncoming, 300 following."},
  dui:{tips:["BAC limits: 0.08% for 21+, 0.04% for commercial drivers, 0.01% if you're under 21.","Under 21 with 0.01% or more = license suspended for 1 year.","You can be arrested below 0.08% if alcohol or drugs affect your driving — and that includes cannabis and medicine.","Implied consent: by driving you've agreed to a breath or blood test if arrested. Refusing = suspension.","Open containers go in the trunk. A DUI stays on your record for 10 years."],trick:"Under 21? Think ZERO. The legal limit (0.01%) is basically one sip."},
  license:{
    adult:["18+ with a permit: you may only drive with a California-licensed driver age 18 or older beside you.","No driver's ed or logged hours required for adults. The law sets no minimum wait before the drive test (confirm when you book).","You can't drive yourself to the DMV for your drive test — bring a licensed driver.","Moved? Tell the DMV your new address within 10 days.","Always carry proof of insurance. Crash without insurance = license suspended up to 4 years."],
    minor:["Permit at 15½. Hold it 6 months and log 50 practice hours (10 at night) before the drive test.","Permit drivers under 18 need a licensed driver 25 or older in the car.","First 12 months of a provisional license: no passengers under 20 and no driving 11 PM–5 AM unless a parent, licensed driver 25+, or instructor is with you.","Under 18: NO cell phone use while driving — not even hands-free.","Moved? Tell the DMV your new address within 10 days."],
    trick:{adult:"Permit = practice partner (18+), never solo — not even to the DMV.",minor:"\"11 to 5, stay alive\" — no solo driving 11 PM to 5 AM your first year."}},
  freeway:{tips:["Speed up on the on-ramp to match freeway traffic before merging.","Missed your exit? Go to the next one. Never back up or stop on the freeway.","Slow down in the exit lane, not on the freeway itself.","Enter and exit carpool lanes only where the lines are broken.","Broke down? Get completely off the road and turn on your hazard lights."],trick:"\"Merge at speed, slow in the exit lane, missed it? Let it go.\""},
  rail:{tips:["Signals flashing at a crossing? Stop 15 to 50 feet from the nearest rail.","Never stop ON tracks — wait until there's room on the other side. Never drive around lowered gates.","Stalled on the tracks with a train coming: everyone out, run TOWARD the train at an angle, away from the tracks.","School bus with flashing red lights: stop and stay stopped until the lights turn off — both directions, unless it's across a divided or multilane highway.","Passing a stopped school bus: up to $1,000 fine and a 1-year suspension."],trick:"Railroad stop zone = \"15 to 50 — that's nifty.\""},
  emerg:{tips:["Crash with injury, death, or over $1,000 damage? Report it to the DMV within 10 days (form SR-1). Injury or death? Also report to police or CHP within 24 hours.","Hit a parked car? Leave a note with your name and address, and notify police.","Brakes fail: pump them, shift to a lower gear, use the parking brake.","Blowout: hold the wheel firmly, ease off the gas, don't slam the brakes.","Stopped by police: pull to the right, stay in the car, show license, registration, and proof of insurance."],trick:"Brake failure = \"Pump, Gear, Park.\""}
};

const Q = [
// ---------- SIGNS & SIGNALS ----------
{t:"signs",s:"octagon",q:"What does this red, eight-sided sign mean?",a:["Come to a complete stop","Slow down and go if no one is coming","Stop only if other cars are at the intersection"],h:"This shape is used for only one sign.",e:"An eight-sided (octagon) sign always means STOP. Stop completely at the limit line, before the crosswalk, or before entering the intersection."},
{t:"signs",q:"At a STOP sign with a white limit line painted on the road, where must you stop?",a:["At the limit line","Past the line, where you can see cross traffic","Inside the crosswalk"],h:"The line is there for a reason.",e:"Stop at the limit line. No limit line? Stop before the crosswalk. Neither? Stop before entering the intersection. You may then creep forward to look."},
{t:"signs",s:"yield",q:"What does this red-and-white triangle sign mean?",a:["Slow down and let traffic and pedestrians go first","You must always come to a full stop","Merge without slowing down"],h:"You only stop if you need to.",e:"YIELD means slow down and be ready to stop so cross traffic and pedestrians can go first."},
{t:"signs",s:"school",q:"A five-sided sign like this means you are:",a:["Near a school or a school crossing","Near a railroad crossing","Entering a construction zone"],h:"Five sides — think five school days.",e:"The pentagon shape (usually fluorescent yellow-green) marks school zones and school crossings."},
{t:"signs",s:"rxr",q:"What does this round yellow sign mean?",a:["A railroad crossing is ahead","Two roads cross ahead","A roundabout is ahead"],h:"Round shape, Railroad — both start with R.",e:"The round railroad advance warning sign tells you to look, listen, and be ready to stop for a train."},
{t:"signs",s:"curve",q:"What do yellow, diamond-shaped signs like this one do?",a:["Warn you about hazards or road conditions ahead","Show the legal speed limit","Give directions to nearby cities"],h:"Yellow means caution.",e:"Diamond = warning: curves, merges, slippery roads, pedestrian crossings, and more."},
{t:"signs",s:"construction",q:"Orange signs like this one mean:",a:["Road work is ahead","A park or recreation area is ahead","A hospital or other service is nearby"],h:"Orange cones, orange signs.",e:"Orange = work zone. Slow down, watch for workers, and know that fines can be doubled."},
{t:"signs",s:"dne",q:"What does this sign mean?",a:["Do not enter — traffic is coming toward you","No parking at any time","No stopping on this road"],h:"It's posted where traffic flows only toward you.",e:"DO NOT ENTER marks a one-way road or ramp you're not allowed to drive into."},
{t:"signs",s:"wrongway",q:"You see this sign facing you as you drive. What should you do?",a:["Safely pull over and turn around","Speed up and look for the next exit","Keep going — the sign is for trucks"],h:"Read it literally.",e:"WRONG WAY means you're driving against traffic, often after turning onto a freeway off-ramp. Pull over safely and turn around."},
{t:"signs",s:"nouturn",q:"What does this sign mean?",a:["No U-turns","No left turns","Sharp curve ahead"],h:"A red circle with a slash means 'not allowed.'",e:"The red circle and slash over a U-shaped arrow means U-turns are not allowed here."},
{t:"signs",s:"smv",q:"An orange triangle with a red border on the back of a vehicle means:",a:["It's a slow-moving vehicle","It's carrying hazardous materials","It's about to make a wide turn"],h:"Think tractors and farm equipment.",e:"This emblem marks vehicles that go 25 mph or less, like farm equipment. Slow down early."},
{t:"signs",s:"light-flash-red",q:"What does a flashing red traffic light mean?",a:["Stop completely, then go when it's safe","Slow down and go through without stopping","The signal is broken, so just yield"],h:"Red always involves stopping.",e:"A flashing red light means the same thing as a STOP sign."},
{t:"signs",s:"light-flash-yellow",q:"What does a flashing yellow traffic light mean?",a:["Slow down and go through with caution","Stop completely, then go","Stop and wait for the light to turn green"],h:"Yellow = caution, not stop.",e:"Flashing yellow = proceed carefully. You don't have to stop."},
{t:"signs",s:"light-red-arrow",q:"What does a steady red arrow mean?",a:["Don't turn that way until the signal turns green","Turn after a full stop if it's clear","Turn if no pedestrians are crossing"],h:"Arrows are stricter than round lights.",e:"A red arrow means STOP. Stay stopped until a green arrow or green light appears — you may not turn on a red arrow."},
{t:"signs",s:"light-yellow",q:"What does a steady yellow light mean?",a:["Red is coming — stop if you can do it safely","Speed up to beat the red light","Green is coming — get ready to go"],h:"It's a warning, not a dare.",e:"Steady yellow warns that the light is about to turn red. Stop if you can do it safely; if you're already in the intersection, carefully continue."},
{t:"signs",s:"light-off",q:"The traffic lights at an intersection are completely dark (not working). You should:",a:["Treat it like a four-way stop","Drive through at normal speed","Yield only to cars on your right"],h:"No lights = everyone stops.",e:"When signals are out, every direction treats the intersection like an all-way stop."},
{t:"signs",s:"light-red",q:"Can you turn right on a steady red light in California?",a:["Yes, after a full stop, unless a sign says no","No, never","Only when there's a green arrow"],h:"California allows it in most places.",e:"After a complete stop, you may turn right on red if it's safe and no sign prohibits it. Yield to pedestrians and traffic first."},
{t:"signs",s:"light-green-arrow",q:"What does a green arrow pointing left mean?",a:["You may turn left — oncoming traffic is stopped","You may turn left only after yielding to oncoming cars","Left turns are not allowed right now"],h:"A green arrow is a 'protected' turn.",e:"With a green arrow, oncoming traffic has a red light. Still yield to any vehicles or pedestrians already in the intersection."},
{t:"signs",s:"light-flash-yellow-arrow",q:"What does a flashing yellow left-turn arrow mean?",a:["You may turn left, but yield to oncoming traffic first","Oncoming traffic is stopped, so turn now","Stop and wait for a green arrow"],h:"Flashing yellow = caution.",e:"A flashing yellow arrow means the turn is allowed but NOT protected. Yield to oncoming traffic and pedestrians, then turn when it's safe."},
{t:"signs",s:"light-green",q:"What does a steady green light mean?",a:["Go, but only if the intersection is clear","Go — you always have the right-of-way","Speed up because it will change soon"],h:"Green isn't a guarantee.",e:"Green means go if it's safe. Yield to vehicles, bicyclists, and pedestrians still in the intersection."},
{t:"signs",s:"pedx",q:"What does this sign warn you about?",a:["A pedestrian crossing","A school bus stop","A playground"],h:"Look at the figure.",e:"Pedestrian crossing ahead — slow down and be ready to yield."},
{t:"signs",q:"Blue road signs show:",a:["Services like gas, food, lodging, and hospitals","Speed rules and other laws","Construction and work zones"],h:"Think of the 'H' for hospital signs.",e:"Blue = motorist services. Green = directions. Orange = road work."},
{t:"signs",q:"Green road signs show:",a:["Directions and distances to places","Warnings about hazards","Laws you must obey"],h:"Freeway exit signs are this color.",e:"Green guide signs tell you where you're going and how far."},
{t:"signs",q:"A red circle with a red slash through a symbol means:",a:["That action is not allowed","Do it with caution","That action is recommended"],h:"It's the universal 'no' symbol.",e:"Red circle + slash = prohibited (no U-turn, no left turn, no parking, and so on)."},
{t:"signs",q:"A pedestrian signal shows a flashing raised hand (or 'DON'T WALK'). This means pedestrians:",a:["Should not start crossing","May start crossing if they hurry","Must wait — the crosswalk is closed all day"],h:"It's counting down.",e:"A flashing hand means don't START crossing. People already in the street may finish, so drivers should watch for them."},
{t:"signs",s:"merge",q:"What does this yellow sign mean?",a:["Traffic from another lane will merge into yours","Your lane ends and you must stop","The road divides into two roads"],h:"Look at the two lines joining.",e:"The merge sign warns that another lane of traffic joins yours. Adjust your speed to let them in smoothly."},
{t:"signs",s:"speed",q:"White rectangular signs like this one are:",a:["Regulatory signs — laws you must obey","Warning signs about hazards","Guide signs for directions"],h:"White rectangles = rules.",e:"White rectangular signs are regulatory: speed limits, turn rules, parking rules."},
{t:"signs",q:"Yellow lines on the road separate:",a:["Traffic moving in opposite directions","Lanes moving in the same direction","Bike lanes from car lanes"],h:"Think of the center line on a two-way road.",e:"Yellow lines separate traffic going opposite ways. White lines separate lanes going the same way."},
{t:"signs",q:"White lane lines separate:",a:["Lanes of traffic going the same direction","Traffic going in opposite directions","Two-way left-turn lanes from other lanes"],h:"Yellow is for opposite directions.",e:"White lines separate lanes going the same way. Yellow lines (including the edges of center turn lanes) separate opposite directions."},

// ---------- SPEED ----------
{t:"speed",s:"speed65",q:"Unless a sign says otherwise, the maximum speed limit on most California highways is:",a:["65 mph","55 mph","70 mph"],h:"70 is only allowed where signs say so.",e:"65 mph is the max on most CA highways. Some freeways are posted at 70."},
{t:"speed",q:"Unless posted otherwise, the speed limit on a two-lane undivided highway is:",a:["55 mph","65 mph","45 mph"],h:"No divider = slower.",e:"Two-lane undivided highways are 55 mph unless posted otherwise."},
{t:"speed",q:"When you're towing a trailer, the speed limit is:",a:["55 mph","65 mph","45 mph"],h:"Same as big trucks.",e:"Vehicles towing trailers are limited to 55 mph and must use the right lane or a marked truck lane."},
{t:"speed",q:"Unless posted otherwise, the speed limit in a residential or business district is:",a:["25 mph","30 mph","35 mph"],h:"The classic neighborhood number.",e:"Residential and business districts are 25 mph unless signs say otherwise."},
{t:"speed",s:"blind",q:"The speed limit at a 'blind' intersection — where you can't see 100 feet both ways during the last 100 feet before crossing — is:",a:["15 mph","25 mph","10 mph"],h:"Tight spots get the lowest number.",e:"Blind intersections are 15 mph. Go slow enough to stop if something appears."},
{t:"speed",q:"Unless posted otherwise, the speed limit in an alley is:",a:["15 mph","20 mph","25 mph"],h:"Alleys are narrow and blind.",e:"Alleys are 15 mph."},
{t:"speed",s:"school",q:"Near a school while children are outside or crossing, unless a lower limit is posted, the speed limit is:",a:["25 mph","35 mph","40 mph"],h:"Same as a neighborhood.",e:"25 mph near schools when children are present. Some school zones are posted at 15 or 20 mph — a 2026 law (AB 382) lets more cities post 20 mph. Always obey the posted sign."},
{t:"speed",q:"Within 100 feet of a railroad crossing where you can't see the tracks for 400 feet in both directions, the speed limit is:",a:["15 mph","25 mph","5 mph"],h:"Same as an alley.",e:"Railroad crossings without a clear view are 15 mph."},
{t:"speed",q:"California's 'Basic Speed Law' means you must:",a:["Never drive faster than is safe for conditions","Always drive exactly at the posted limit","Drive under 55 mph in bad weather"],h:"It's about conditions, not numbers.",e:"Even under the limit, you can be ticketed if you're going too fast for rain, fog, traffic, or other conditions."},
{t:"speed",q:"The posted limit is 65 mph, but there's thick fog. What's the legal speed?",a:["Whatever speed is safe in the fog","65 mph, because it's posted","Anything up to 70 mph"],h:"Think about the Basic Speed Law.",e:"The Basic Speed Law means the safe speed for conditions can be far below the posted limit."},
{t:"speed",q:"When passing a senior center with a 'SENIOR' warning sign, the speed limit is usually:",a:["25 mph","15 mph","35 mph"],h:"Same as school zones.",e:"Senior zones are 25 mph where posted."},
{t:"speed",q:"On a wet road, you should slow down by about:",a:["5 to 10 mph","20 to 25 mph","You don't need to slow down"],h:"A small but real drop.",e:"Slow down 5–10 mph on wet roads. On packed snow, cut your speed in half."},
{t:"speed",q:"On packed snow, you should:",a:["Cut your speed about in half","Slow down by about 5 mph","Drive at the posted limit"],h:"Snow is much worse than rain.",e:"Reduce your speed by half on packed snow."},
{t:"speed",q:"On an icy road, you should slow to no more than:",a:["5 mph","15 mph","25 mph"],h:"Ice is the slipperiest surface there is.",e:"On ice, slow to a crawl — no more than 5 mph."},
{t:"speed",q:"Driving much slower than the flow of traffic:",a:["Can be dangerous and can get you a ticket","Is always the safest choice","Is required in the left lane"],h:"Other drivers have to swerve around you.",e:"Blocking normal traffic is illegal and causes crashes. Use the right lane if you're going slower."},

// ---------- RIGHT-OF-WAY ----------
{t:"row",s:"4way",q:"At a four-way stop, two cars arrive at the same time. Which goes first?",a:["The car on the right","The car on the left","The car going straight"],h:"Right goes first.",e:"When two cars arrive together, the driver on the left yields to the driver on the right."},
{t:"row",q:"Several cars are waiting at a four-way stop. Who gets to go first?",a:["The driver who stopped first","The driver on the left","The driver going straight"],h:"First come, first served.",e:"At an all-way stop, the first vehicle to stop goes first. If two stop at the same time, the one on the right goes first."},
{t:"row",q:"At an intersection with no stop signs or signals, you should yield to:",a:["Cars that got there first or are already in it","Cars coming from your left","No one, if you're going straight"],h:"Whoever is already there.",e:"At uncontrolled intersections, yield to vehicles already in the intersection or that arrived first. If you arrive together, yield to the car on your right."},
{t:"row",q:"At a T-intersection with no signs or signals, who has the right-of-way?",a:["Traffic on the through road","Traffic turning onto the through road","Whoever is going faster"],h:"The road that keeps going wins.",e:"Drivers on the ending road (the stem of the T) must yield to traffic on the through road."},
{t:"row",q:"You're turning left on a green light (no arrow). You must:",a:["Yield to oncoming cars and pedestrians","Turn first because you signaled","Turn before oncoming cars start moving"],h:"Left waits.",e:"Left-turning drivers yield to oncoming traffic close enough to be a hazard, and to pedestrians."},
{t:"row",q:"You're turning right on a green light, and a pedestrian is in the crosswalk you're about to cross. You should:",a:["Wait for them to finish crossing","Turn quickly before they reach your lane","Honk and then turn"],h:"People in the crosswalk come first.",e:"Yield to pedestrians in the crosswalk before turning, even on a green light."},
{t:"row",q:"A pedestrian is waiting to cross at a corner with no painted crosswalk lines. You should:",a:["Stop and let them cross","Keep going — there's no crosswalk","Honk so they know to wait"],h:"Most corners have 'invisible' crosswalks.",e:"Every intersection corner has a crosswalk, even if it isn't painted. Pedestrians there have the right-of-way."},
{t:"row",q:"A pedestrian using a white cane or guide dog is about to cross. You should:",a:["Stop and let them cross — and don't honk","Honk so they know you're there","Drive around them slowly"],h:"Honking could confuse them.",e:"Blind pedestrians always have the right-of-way. Don't honk, and don't stop in the crosswalk."},
{t:"row",q:"You've stopped for a blind pedestrian. They pull in their cane and step back from the curb. This usually means:",a:["You may go","They need help crossing","You must wait until they walk away"],h:"It's a signal to you.",e:"When a blind pedestrian pulls in their cane and steps away from the intersection, it usually means you may go."},
{t:"row",q:"A pedestrian is crossing in the middle of the block, not at a crosswalk. You:",a:["Must still yield and avoid hitting them","Have the right-of-way, so keep going","Should honk and keep driving"],h:"Safety beats who's 'right.'",e:"Even if they aren't at a crosswalk, you must do everything you can to avoid hitting them."},
{t:"row",s:"roundabout",q:"When entering a roundabout, you should:",a:["Yield to cars already in it and go counterclockwise","Enter first — entering traffic has priority","Drive clockwise around the center"],h:"Cars in the circle keep moving.",e:"Yield to circulating traffic, then travel counterclockwise (to the right)."},
{t:"row",q:"You're pulling out of a driveway or parking lot onto a street. You must:",a:["Yield to vehicles and pedestrians","Pull out — street traffic must stop for you","Honk, then pull out"],h:"You're the one joining.",e:"Drivers entering from a driveway, alley, or parking lot must yield to everyone on the road and sidewalk."},
{t:"row",q:"Your light turns green, but traffic is backed up across the intersection. You should:",a:["Wait until you can get all the way across","Pull in and wait in the middle","Go — green means you have the right-of-way"],h:"Don't block the box.",e:"Never enter an intersection unless you can get all the way through. Blocking it is illegal."},
{t:"row",q:"A funeral procession is passing through an intersection. You should:",a:["Yield and let the whole procession pass","Cut in when there's a gap","Honk to hurry them along"],h:"Show respect and patience.",e:"Funeral processions have the right-of-way. Don't cut into or interrupt them."},
{t:"row",q:"Which statement about the right-of-way is true?",a:["Never insist on it if it could cause a crash","Always take it when it's yours","Only emergency vehicles have it"],h:"It's given, not taken.",e:"The law says who must yield, but you should always give up the right-of-way to prevent a collision."},
{t:"row",q:"On a narrow mountain road, two cars meet and there isn't room to pass. Who must back up?",a:["The car facing downhill","The car facing uphill","Whichever car is smaller"],h:"Backing uphill is easier to control.",e:"The vehicle facing downhill must back up until the uphill vehicle can pass."},

// ---------- LANES / TURNS / PASSING ----------
{t:"lanes",q:"You must signal at least how far before you turn?",a:["100 feet","50 feet","200 feet"],h:"About the length of 6–7 cars.",e:"Signal for the last 100 feet before you turn."},
{t:"lanes",q:"On a freeway, signal at least how long before changing lanes?",a:["5 seconds","2 seconds","10 seconds"],h:"Freeway speeds need more warning.",e:"Signal at least 5 seconds before changing lanes on a freeway."},
{t:"lanes",s:"twlt",q:"You may drive in a center two-way left-turn lane for no more than:",a:["200 feet","500 feet","100 feet"],h:"Same distance as entering a bike lane to turn.",e:"Use the center left-turn lane only to start or finish a left turn (or a legal U-turn), and for no more than 200 feet."},
{t:"lanes",s:"bikelane",q:"You're making a right turn and there's a bike lane next to the curb. You should:",a:["Merge into the bike lane within 200 feet of the turn","Turn across the bike lane from your lane","Enter the bike lane a full block early"],h:"Get to the curb so bikes can't pass on your right.",e:"Check for bikes, signal, and move into the bike lane no more than 200 feet before the corner, then turn."},
{t:"lanes",s:"dblyellow",q:"Two solid yellow lines down the center of the road mean:",a:["No passing — but you may cross to turn left into a driveway","You may pass if the road ahead is clear","There's a carpool lane ahead"],h:"Solid lines don't let you pass.",e:"Double solid yellow = no passing. You may cross them to turn left into a driveway or private road."},
{t:"lanes",q:"A broken yellow center line on your side of the road means:",a:["You may pass if it's safe","You may never pass","You're in a bike lane"],h:"Broken = OK with care.",e:"A broken yellow line lets you pass when the way is clear and safe."},
{t:"lanes",q:"Two sets of double yellow lines, two or more feet apart, mean:",a:["Treat them like a wall — never cross","You may cross them to pass","It's a center left-turn lane"],h:"Twice the lines, twice as serious.",e:"Two sets of solid double yellow lines spaced 2+ feet apart are a barrier. Don't drive over them or turn across them, except at marked openings."},
{t:"lanes",q:"Two solid white lines (like those next to a carpool lane) mean:",a:["Do not cross them","Cross them when traffic is clear","Change lanes freely"],h:"Treat them like a wall.",e:"Double solid white lines are a barrier. Never cross them to enter or exit a lane."},
{t:"lanes",q:"After passing a car, when is it safe to return to your lane?",a:["When you can see its headlights in your rearview mirror","As soon as your back bumper clears its front bumper","After counting two seconds"],h:"Use your mirror.",e:"Seeing the car's headlights in your rearview mirror means you have enough space."},
{t:"lanes",q:"Before changing lanes, you should:",a:["Check mirrors, signal, and look over your shoulder","Signal and change lanes right away","Honk and move over"],h:"Mirrors can't see everything.",e:"Mirrors miss your blind spot — always turn your head and look over your shoulder."},
{t:"lanes",q:"In a residential district, a U-turn is legal when:",a:["No vehicles are coming within 200 feet","There's any gap in traffic","Never"],h:"200 feet again.",e:"U-turns in residential areas are OK if no vehicle is approaching within 200 feet, or if a sign or signal protects you."},
{t:"lanes",q:"Which of these U-turns is ILLEGAL?",a:["A U-turn on a one-way street","A U-turn across a double yellow line where it's safe","A U-turn in a residential area with no cars within 200 feet"],h:"Where would you be facing after?",e:"Never make a U-turn on a one-way street — you'd be driving the wrong way."},
{t:"lanes",q:"A U-turn is illegal where you can't see clearly for how far in each direction?",a:["200 feet","100 feet","50 feet"],h:"The same number as the residential U-turn rule.",e:"Never U-turn where you can't see 200 feet each way — because of a curve, hill, rain, fog, or anything else."},
{t:"lanes",q:"A left turn on a red light is allowed only:",a:["From a one-way street onto another one-way street","At any intersection after a full stop","Never in California"],h:"Both streets must flow the same way.",e:"After a full stop, you may turn left on red from a one-way street onto a one-way street going left, unless a sign says no."},
{t:"lanes",q:"When turning left from a two-way street onto another two-way street, you should:",a:["Start near the center line and end in the left lane","End in the far-right lane","Swing wide into any open lane"],h:"Stay in the matching lane.",e:"Start close to the center line and end in the left lane of the new street, then move over when it's safe."},
{t:"lanes",q:"When making a right turn, you should:",a:["Start and end the turn close to the right curb","Swing wide into the left lane first","End the turn in the far-left lane"],h:"Hug the right side.",e:"Begin and end a right turn close to the right edge of the road. Don't swing wide."},
{t:"lanes",s:"hand-left",q:"A driver sticks their left arm straight out the window. They plan to:",a:["Turn left","Turn right","Slow down or stop"],h:"Point where you're going.",e:"Arm straight out = left turn."},
{t:"lanes",s:"hand-right",q:"A driver's left arm is out the window and bent upward at the elbow. They plan to:",a:["Turn right","Turn left","Slow down or stop"],h:"The arm points up and over the car.",e:"Arm bent up = right turn."},
{t:"lanes",s:"hand-stop",q:"A driver's left arm is out the window and pointed down. They plan to:",a:["Slow down or stop","Turn left","Turn right"],h:"Down = down in speed.",e:"Arm bent down = slowing or stopping."},
{t:"lanes",q:"You may pass another vehicle on the right when:",a:["There are two or more lanes going your way","There's a wide, paved shoulder","Never in California"],h:"Never drive off the road to do it.",e:"Passing on the right is OK on roads with 2+ lanes your way, or around a car turning left — but never on the shoulder."},
{t:"lanes",q:"On a two-lane road, you may not pass within how many feet of an intersection, bridge, tunnel, or railroad crossing?",a:["100 feet","500 feet","50 feet"],h:"Same as the turn-signal distance.",e:"Don't pass within 100 feet of intersections, bridges, tunnels, or railroad crossings."},
{t:"lanes",q:"If you're driving slower than other traffic on a road with several lanes, use the:",a:["Right lane","Left lane","Center lane"],h:"Keep the fast lane clear.",e:"Slower traffic keeps right. The left lane is for passing."},

// ---------- PARKING ----------
{t:"parking",s:"hydrant",q:"You may not park within how many feet of a fire hydrant?",a:["15 feet","10 feet","25 feet"],h:"About the length of one car.",e:"Stay at least 15 feet from fire hydrants."},
{t:"parking",q:"You may not park within how many feet of a crosswalk?",a:["20 feet","5 feet","50 feet"],h:"It keeps pedestrians visible.",e:"California's 'daylighting' law bans parking within 20 feet of a marked or unmarked crosswalk (15 feet if there's a curb extension)."},
{t:"parking",q:"You may not park within how many feet of a sidewalk ramp for wheelchairs?",a:["3 feet","10 feet","15 feet"],h:"A short one.",e:"Keep 3 feet clear of wheelchair ramps."},
{t:"parking",q:"You may not park closer than how far to the nearest railroad track?",a:["7½ feet","3 feet","20 feet"],h:"It's a number with a half.",e:"Park at least 7½ feet from the nearest rail."},
{t:"parking",q:"When parallel parking, your wheels must be within how far of the curb?",a:["18 inches","24 inches","36 inches"],h:"A foot and a half.",e:"Park parallel and within 18 inches of the curb."},
{t:"parking",s:"hill-down",q:"You're parking DOWNHILL next to a curb. Turn your front wheels:",a:["Toward the curb","Away from the curb","Straight ahead"],h:"If the car rolls, the curb should catch it.",e:"Downhill: turn your wheels into the curb so the car rolls into it, not into traffic."},
{t:"parking",s:"hill-up",q:"You're parking UPHILL next to a curb. Turn your front wheels:",a:["Away from the curb","Toward the curb","Straight ahead"],h:"Up and away.",e:"Uphill with a curb: turn your wheels away from the curb (to the left), then let the car roll back a few inches so the tire rests against the curb."},
{t:"parking",q:"You're parking on a hill with NO curb. Which way should your front wheels point?",a:["Toward the side of the road","Toward the middle of the road","Straight ahead"],h:"If it rolls, it should leave the road, not enter traffic.",e:"No curb? Turn your wheels toward the edge of the road, uphill or downhill."},
{t:"parking",s:"curb-red",q:"What does a red curb mean?",a:["No stopping, standing, or parking","Loading and unloading only","Parking for 10 minutes"],h:"Red = stop rules.",e:"Red curbs are completely off-limits (buses may stop at red bus zones)."},
{t:"parking",s:"curb-white",q:"At a white curb, you may stop:",a:["Only to pick up or drop off passengers or mail","Only if you have a disabled placard","For up to two hours"],h:"White = wait briefly.",e:"White curbs are for quick passenger or mail stops only."},
{t:"parking",s:"curb-green",q:"What does a green curb mean?",a:["You may park for a limited time","Pick-up and drop-off only","Emergency vehicles only"],h:"Green = go, but not forever.",e:"Green curbs allow short, time-limited parking (the limit is posted or painted)."},
{t:"parking",s:"curb-yellow",q:"What does a yellow curb mean?",a:["Stop only to load or unload passengers or freight","Park as long as you like","Disabled parking only"],h:"Think delivery trucks.",e:"Yellow curbs are loading zones, for no longer than the posted time. Non-commercial drivers usually must stay with the vehicle."},
{t:"parking",s:"curb-blue",q:"Who may park at a blue curb?",a:["Only vehicles with a disabled placard or plates","Buses and taxis","Police and fire vehicles"],h:"Matches the disabled parking symbol.",e:"Blue = disabled parking only. Fines are steep."},
{t:"parking",q:"The striped (crosshatched) area next to a disabled parking space is:",a:["Never a place to park","OK for a quick stop","OK to use at night"],h:"Wheelchairs and ramps need that room.",e:"Those stripes are for wheelchair lifts and access — parking there is illegal."},
{t:"parking",q:"Which of these is a place you may NEVER park?",a:["In a tunnel or on a crosswalk","Next to a green curb","Along an unpainted curb"],h:"Think about blocking people's path.",e:"Never park in a tunnel, on a crosswalk, on a sidewalk, or on most bridges."},
{t:"parking",q:"'Double parking' (stopping next to a car already parked at the curb) is:",a:["Illegal","OK for under 5 minutes","OK with your hazard lights on"],h:"Hazard lights don't make it legal.",e:"Double parking is illegal, even for a minute."},

// ---------- SHARING THE ROAD ----------
{t:"share",s:"bike3ft",q:"When passing a bicyclist in your lane, you must leave at least:",a:["3 feet","1 foot","6 inches"],h:"About an arm's length plus.",e:"California law requires at least 3 feet. If you can't give that much room, slow down and wait."},
{t:"share",q:"You come up behind a bicyclist, and there's an open lane next to you going the same way. You should:",a:["Change lanes to pass, if it's safe","Pass the bike within your lane","Honk so the rider moves over"],h:"A newer law (2023).",e:"California now requires drivers to change lanes to pass a bicyclist when another lane is available. If not, give at least 3 feet."},
{t:"share",s:"siren",q:"An ambulance with lights and siren is coming up behind you. You should:",a:["Pull to the right edge of the road and stop","Speed up to get out of its way","Stop right where you are"],h:"Right and stop.",e:"Drive to the right edge of the road and stop until it passes."},
{t:"share",q:"You're in the middle of an intersection when you hear a siren behind you. You should:",a:["Drive through it, then pull right and stop","Stop in the intersection immediately","Back up out of the intersection"],h:"Don't block the intersection.",e:"Never stop inside an intersection. Continue through, then pull to the right and stop."},
{t:"share",q:"It's illegal to follow within how many feet of a fire truck, ambulance, or police car using its siren?",a:["300 feet","100 feet","50 feet"],h:"Football-field distance.",e:"Stay at least 300 feet behind an emergency vehicle using lights and siren."},
{t:"share",q:"A tow truck is stopped on the freeway shoulder with flashing lights. You must:",a:["Move over a lane if safe, or slow down","Keep your speed — it's on the shoulder","Stop behind it"],h:"Slow Down, Move Over.",e:"California's move-over law covers emergency vehicles, tow trucks, and Caltrans vehicles with lights flashing."},
{t:"share",q:"As of 2026, California's 'Slow Down, Move Over' law also covers:",a:["Any stopped vehicle with its hazard lights flashing","Only police cars","Only tow trucks"],h:"The law got much broader.",e:"New in 2026 (AB 390): move over — or slow down if you can't — for ANY stopped vehicle showing hazard lights or warning devices."},
{t:"share",s:"truck",q:"The red areas around this truck are its 'No Zones.' What are they?",a:["Blind spots where the driver can't see you","Areas where it's safe to pass","Lanes reserved for motorcycles"],h:"Big vehicles, big blind spots.",e:"Trucks have large blind spots in front, behind, and on both sides — biggest on the right. Don't linger there."},
{t:"share",q:"Which is true about large trucks?",a:["They need more distance to stop than cars","They can stop faster than cars","It's safe to cut in front of them"],h:"Heavier = longer to stop.",e:"Big rigs need much more room to stop. Don't cut in close in front of them."},
{t:"share",q:"If you can't see a truck driver's face in the truck's side mirror:",a:["The driver can't see you either","You're at a safe distance","The driver can see you clearly"],h:"Mirrors work both ways.",e:"If you can't see the driver in their mirror, you're in a blind spot. Move ahead or drop back."},
{t:"share",q:"A large truck is turning right and swings wide to the left first. You should:",a:["Stay back — don't squeeze in on its right","Pass it quickly on the right","Honk so the driver sees you"],h:"That gap will close.",e:"Trucks swing wide to turn right. Never try to slip into the space on their right."},
{t:"share",s:"moto",q:"When sharing the road with a motorcycle, you should:",a:["Give it a full lane and extra following room","Share the lane with it side by side","Follow closely so the rider sees you"],h:"Motorcycles get a whole lane, like cars.",e:"Never share a lane with a motorcycle. Leave 3+ seconds of following distance."},
{t:"share",q:"Motorcycles riding between lanes of slow or stopped traffic ('lane splitting') is:",a:["Legal in California — don't block them","Illegal in California","Allowed for cars, too"],h:"California was the first state to make it official.",e:"Lane splitting is legal in CA. Never block a motorcyclist or open a door in their path."},
{t:"share",q:"You may drive in a bike lane:",a:["Only to park, enter the road, or within 200 feet of a turn","Anytime traffic is slow","Only at night"],h:"It's mainly for bikes.",e:"Cars use a bike lane only briefly: to park where allowed, to enter or leave the road, or within 200 feet of a turn."},
{t:"share",q:"Before opening your car door on the street side, you should:",a:["Check for bicycles and traffic","Open it quickly to get out fast","Nothing — riders must avoid you"],h:"Doors can knock riders down.",e:"Look in your mirror and over your shoulder for cyclists before opening your door."},
{t:"share",q:"A ball rolls into the street ahead of you. You should:",a:["Slow down — a child may run after it","Honk and keep going","Swerve around it"],h:"Balls are usually chased.",e:"Children often follow balls into the street. Slow down and be ready to stop."},
{t:"share",q:"Bicyclists riding on the road:",a:["Have the same rights and duties as drivers","Must always ride on the sidewalk","Don't have to obey traffic laws"],h:"Treat them like a vehicle.",e:"Bicyclists must obey traffic laws and have the right to use the road."},
{t:"share",q:"A streetcar stops to let passengers off, and there's no safety zone. You should:",a:["Stop behind its nearest door and wait","Pass on the left","Pass quickly on the right"],h:"Passengers are stepping into the street.",e:"Stop behind the nearest door until passengers have safely crossed."},
{t:"share",q:"You come up on a person riding a horse. You should:",a:["Slow down, give plenty of room, and don't honk","Honk to warn the rider","Pass quickly to get by"],h:"Horses spook easily.",e:"Pass slowly and widely, without loud noises."},

// ---------- SAFE DRIVING ----------
{t:"safe",s:"3sec",q:"On a dry road in good weather, a safe following distance is at least:",a:["3 seconds","1 second","10 seconds"],h:"Count 'one-thousand-one, two, three.'",e:"When the car ahead passes a marker, count. You shouldn't reach the marker before you finish 'one-thousand-three.'"},
{t:"safe",q:"You should increase your following distance when:",a:["The road is wet or you're being tailgated","Traffic is light","It's a clear, sunny day"],h:"Anything that means you need more room to stop.",e:"Add space in bad weather, behind motorcycles and big trucks, and when someone is tailgating you."},
{t:"safe",q:"To spot hazards early, you should look how far ahead?",a:["10 to 15 seconds","2 to 3 seconds","1 minute"],h:"About a city block.",e:"Look 10–15 seconds ahead so you can spot problems early."},
{t:"safe",s:"night",q:"Your headlights must be on:",a:["From 30 minutes after sunset to 30 minutes before sunrise","Only after it's completely dark","Only when it's raining"],h:"There's a 30-minute buffer.",e:"Headlights on from 30 minutes after sunset to 30 minutes before sunrise, and whenever you need them to see."},
{t:"safe",q:"You must also turn on your headlights when:",a:["Your wipers are on, or you can't see 1,000 feet","You're on a freeway","You're parked on the shoulder"],h:"Wipers on = lights on.",e:"If it's raining enough for wipers, or you can't see 1,000 feet ahead, your headlights must be on."},
{t:"safe",q:"Dim your high beams when an oncoming car is within:",a:["500 feet","1,000 feet","100 feet"],h:"The bigger of the two high-beam numbers.",e:"Switch to low beams within 500 feet of oncoming traffic."},
{t:"safe",q:"Dim your high beams when you're following a car within:",a:["300 feet","50 feet","1,000 feet"],h:"The smaller high-beam number.",e:"Use low beams within 300 feet of a car you're following."},
{t:"safe",s:"fog",q:"When driving in fog, you should use:",a:["Low-beam headlights","High-beam headlights","Parking lights only"],h:"High beams bounce back at you.",e:"High beams reflect off fog and blind you. Use low beams and slow down."},
{t:"safe",q:"The fog gets so thick you can barely see. The safest choice is to:",a:["Pull completely off the road and wait","Follow the taillights ahead closely","Turn on your high beams"],h:"Sometimes the best move is not to drive.",e:"If fog is that thick, pull completely off the road, turn on your hazard lights, and wait for it to clear."},
{t:"safe",q:"An oncoming car's bright lights are blinding you. You should:",a:["Look toward the right edge of your lane","Stare at the car's headlights","Flash and keep on your high beams"],h:"Use the white edge line as a guide.",e:"Glance at the right edge of the road to stay on track without being blinded."},
{t:"safe",q:"Someone is tailgating you. What's the best thing to do?",a:["Change lanes or slow down gently to let them pass","Brake hard to warn them","Speed up"],h:"Get them away from your bumper.",e:"Let tailgaters go by. Never brake-check — that causes crashes."},
{t:"safe",q:"Your car starts to skid on a slippery road. You should:",a:["Ease off the gas and steer where you want to go","Slam on the brakes","Steer away from where you want to go"],h:"Look and steer toward your target.",e:"Take your foot off the gas and steer smoothly in the direction you want the front of the car to go."},
{t:"safe",q:"Roads are often MOST slippery:",a:["During the first rain after a dry spell","After it has rained for hours","On hot, dry days"],h:"Oil builds up on dry roads.",e:"The first rain lifts oil to the surface, making roads extra slick."},
{t:"safe",q:"Hydroplaning (tires riding on water) is most likely when you:",a:["Drive fast on a wet road, especially with worn tires","Drive slowly in light rain","Drive on dry pavement"],h:"Speed and water together.",e:"At higher speeds, tires can ride up on a film of water. Slow down in rain."},
{t:"safe",q:"The best way to check your blind spot is to:",a:["Turn your head and look over your shoulder","Use your mirrors only","Tap your horn first"],h:"Mirrors have gaps.",e:"Quick shoulder checks catch what mirrors miss."},
{t:"safe",q:"To stay safe from your airbag, sit at least how far from the steering wheel?",a:["10 inches","2 inches","5 inches"],h:"About the length of a pencil.",e:"Sit at least 10 inches from the steering wheel."},
{t:"safe",q:"Children under 8 must ride:",a:["In a car seat or booster seat in the back seat","In the front seat with a seat belt","Anywhere, as long as they wear a belt"],h:"The back seat is safest for kids.",e:"Kids under 8 must be in a proper car seat or booster seat in the back seat."},
{t:"safe",q:"Children under 2 must ride in a rear-facing car seat unless they:",a:["Weigh 40+ pounds or are 40+ inches tall","Are going a short distance","Sit in the back seat"],h:"Two numbers, both 40.",e:"Kids under 2 ride rear-facing unless they weigh 40 pounds or more, or are 40 inches tall or more."},
{t:"safe",q:"Leaving a child age 6 or younger alone in a car is:",a:["Illegal unless someone 12 or older is watching them","OK for a few minutes","OK with the windows cracked"],h:"Cars heat up fast.",e:"It's illegal to leave a child 6 or younger without supervision by someone at least 12."},
{t:"safe",q:"Smoking in a car while someone under 18 is inside is:",a:["Illegal, even with the windows down","Legal if a window is open","Legal if the car is parked"],h:"Protecting kids' lungs.",e:"It's illegal to smoke in a vehicle with a minor in it, whether it's moving or parked."},
{t:"safe",q:"Drivers 18 and older may use a cell phone while driving only if it's:",a:["Hands-free, mounted, and used with one tap or swipe","Held in your hand at red lights","Used for texting at stop signs"],h:"No holding it at all.",e:"Adults must use phones hands-free. You may tap or swipe once on a mounted phone. Drivers under 18 can't use phones at all."},
{t:"safe",q:"Wearing headphones or earbuds in both ears while driving is:",a:["Illegal","Legal","Legal only at night"],h:"You need to hear sirens.",e:"You can't cover or plug both ears while driving."},
{t:"safe",q:"You start feeling drowsy on a long drive. You should:",a:["Pull over somewhere safe and rest","Open the window and keep going","Turn the music up loud"],h:"Only sleep fixes sleepiness.",e:"Drowsy driving is like drunk driving. Stop and rest."},
{t:"safe",q:"Throwing trash from a car can lead to a fine of up to:",a:["$1,000","$50","$10"],h:"California takes litter seriously.",e:"Littering from a vehicle can cost up to $1,000."},
{t:"safe",q:"When should you use your horn?",a:["To help avoid a collision","To show you're annoyed","To hurry up a slow driver"],h:"It's a safety tool.",e:"Use your horn to warn others and avoid crashes, not to express frustration."},
{t:"safe",q:"Who must wear a seat belt?",a:["The driver and every passenger","Only people in the front seat","Only the driver"],h:"Every seat, every trip.",e:"Everyone in the car must be buckled up (kids in proper car seats)."},
{t:"safe",q:"Coming up to a sharp curve, you should:",a:["Slow down before you enter the curve","Brake hard in the middle of the curve","Speed up through the curve"],h:"Do your braking on the straight part.",e:"Brake before the curve. Braking hard in a curve can make you skid."},
{t:"safe",q:"At night, 'overdriving your headlights' means:",a:["Going too fast to stop within the distance you can see","Using high beams near other cars","Driving with only parking lights on"],h:"Can you stop in time for what you can't see yet?",e:"Drive slowly enough that you can stop within the distance your headlights light up."},

// ---------- ALCOHOL & DRUGS ----------
{t:"dui",s:"nodrink",q:"For drivers 21 and older, it's illegal to drive with a blood alcohol concentration (BAC) of:",a:["0.08% or higher","0.10% or higher","0.12% or higher"],h:"The well-known adult limit.",e:"0.08% is the adult limit. You can still be arrested below it if you're impaired."},
{t:"dui",q:"For drivers under 21, it's illegal to drive with a BAC of:",a:["0.01% or higher","0.05% or higher","0.08% or higher"],h:"Basically zero tolerance.",e:"Under 21, 0.01% (about one sip) is over the limit."},
{t:"dui",q:"Commercial drivers may not drive with a BAC of:",a:["0.04% or higher","0.08% or higher","0.10% or higher"],h:"Half the adult limit.",e:"Commercial drivers (and for-hire drivers carrying passengers) have a 0.04% limit."},
{t:"dui",q:"Can you be arrested for DUI with a BAC below 0.08%?",a:["Yes, if alcohol or drugs affect your driving","No, 0.08% is the only limit","Only if you cause a crash"],h:"The number isn't the whole story.",e:"If alcohol or drugs impair your driving, you can be arrested for DUI at any BAC."},
{t:"dui",q:"California's 'implied consent' law means:",a:["By driving, you agree to a chemical test if arrested for DUI","You can refuse any DUI test without penalty","Tests only happen with a lawyer present"],h:"You agreed when you got your license.",e:"Refusing the breath, blood, or urine test leads to license suspension or revocation."},
{t:"dui",q:"A driver under 21 caught with a BAC of 0.01% or more will:",a:["Lose their license for 1 year","Get a warning","Get a 30-day suspension"],h:"It's serious.",e:"Under 21 at 0.01% or more = one-year license suspension."},
{t:"dui",q:"If you're under 21, when may you carry alcohol in a car?",a:["With a parent or other adult named by law, and it's sealed","Any time, if the container is unopened","Any time, if it's in the trunk"],h:"There's a supervision rule AND a container rule.",e:"Under 21, you may only carry alcohol if you're with a parent or other person named by law and the container is full, sealed, and unopened (or it's for your job)."},
{t:"dui",q:"Where must an opened container of alcohol or cannabis be kept while driving?",a:["In the trunk","Under a seat","In the glove box"],h:"Out of reach of everyone in the car.",e:"Opened containers must be in the trunk, or an area where passengers don't sit. The glove box counts as the passenger area."},
{t:"dui",q:"Driving while impaired by marijuana is:",a:["Illegal — it's a DUI","Legal, since cannabis is legal","Legal with a medical card"],h:"Legal to buy ≠ legal to drive on.",e:"Driving impaired by any drug, including cannabis, is a DUI."},
{t:"dui",q:"Prescription or over-the-counter medicine:",a:["Can impair you and lead to a DUI","Never counts toward a DUI","Only matters if mixed with alcohol"],h:"Read the warning label.",e:"Many medicines cause drowsiness. You can be charged with DUI if they impair your driving."},
{t:"dui",q:"What actually sobers you up after drinking?",a:["Only time","Coffee","A cold shower"],h:"Your liver can't be rushed.",e:"Nothing speeds it up. Only time lowers your BAC."},
{t:"dui",q:"Alcohol affects which of these first?",a:["Your judgment","Your hearing","Your sense of smell"],h:"It's why people think they're fine to drive.",e:"Judgment goes first, so impaired drivers often don't realize they're impaired."},
{t:"dui",q:"A DUI conviction stays on your driving record for:",a:["10 years","1 year","3 years"],h:"A long time.",e:"DUI convictions stay on your driving record for 10 years."},

// ---------- LICENSES & INSURANCE ----------
{t:"license",s:"permit",who:"adult",q:"You're 18 or older and have an instruction permit. Who must be with you when you drive?",a:["A California-licensed driver age 18 or older","Anyone who also has a permit","No one — adults may drive alone"],h:"A licensed adult, but not 25 like for teens.",e:"An adult permit lets you practice only with a California-licensed driver who is at least 18, sitting close enough to take control of the car."},
{t:"license",q:"With an instruction permit, may you drive yourself alone to the DMV for your driving test?",a:["No — a licensed driver must ride with you","Yes, the test day is an exception","Yes, if it's during daylight"],h:"A permit never means solo driving.",e:"Permit holders may never drive alone — including to and from the DMV. Bring a licensed driver."},
{t:"license",q:"After you move, you must give the DMV your new address within:",a:["10 days","30 days","90 days"],h:"Ten fingers, ten days.",e:"Update your address with the DMV within 10 days of moving (you can do it online)."},
{t:"license",q:"If you're in a crash and don't have insurance, your license can be suspended for up to:",a:["4 years","6 months","1 month"],h:"Longer than you'd think.",e:"California requires financial responsibility (usually insurance). Crash without it and you can lose your license for up to 4 years."},
{t:"license",q:"You must carry proof of insurance:",a:["Every time you drive","Only on long trips","Only during your first year"],h:"Always in the car.",e:"California requires proof of financial responsibility whenever you drive."},
{t:"license",q:"A California driver's license that says 'provisional' belongs to a driver who is:",a:["Under 18","Over 65","New to California"],h:"Think about teen rules.",e:"Licenses issued to drivers under 18 are marked 'provisional' and come with passenger and nighttime limits."},
{t:"license",who:"minor",q:"During the first 12 months with a provisional license, you may NOT drive passengers under 20 unless:",a:["A parent, licensed adult 25+, or instructor is with you","It's a weekend","They're your brothers or sisters"],h:"There's an adult supervision exception.",e:"For the first year, no passengers under 20 without a qualified adult in the car (unless you have an approved exception)."},
{t:"license",who:"minor",q:"During the first 12 months of a provisional license, you may not drive between:",a:["11 PM and 5 AM","10 PM and 6 AM","Midnight and 6 AM"],h:"'11 to 5, stay alive.'",e:"No driving 11 PM–5 AM in your first year unless a qualified adult is with you or you have an approved exception."},
{t:"license",who:"minor",q:"Drivers under 18 may use a cell phone while driving:",a:["Not at all, except to call for help in an emergency","Hands-free only","Only at red lights"],h:"Stricter than the adult rule.",e:"Minors can't use any wireless device while driving, even hands-free, except to call for help in an emergency."},
{t:"license",who:"minor",q:"If you're under 18 with an instruction permit, you may only drive with:",a:["A licensed California driver 25 or older","Any licensed driver","Any adult 18 or older"],h:"Older than the adult-permit rule.",e:"A licensed parent, guardian, spouse, adult 25+, or instructor must be in the car."},
{t:"license",who:"minor",q:"Before taking the driving test, a minor must hold an instruction permit for at least:",a:["6 months","3 months","12 months"],h:"Half a year.",e:"Hold your permit at least 6 months before the behind-the-wheel test."},
{t:"license",who:"minor",q:"How many hours of supervised practice must a minor log before the drive test?",a:["50 hours, including 10 at night","30 hours, including 5 at night","100 hours, including 20 at night"],h:"Fifty and ten.",e:"A parent or guardian certifies 50 practice hours, with 10 after dark."},
{t:"license",who:"minor",q:"The youngest age you can apply for an instruction permit in California is:",a:["15½","16","15"],h:"Half a year before 16.",e:"You can apply at 15½ with driver's ed completed or in progress."},
{t:"license",who:"minor",q:"The youngest age you can get a provisional driver's license is:",a:["16","15½","17"],h:"Sweet sixteen.",e:"You must be at least 16, have held your permit 6 months, and pass the drive test."},
{t:"license",who:"minor",q:"Which is NOT an allowed exception to the provisional passenger and nighttime rules?",a:["Driving friends to a party","A medical need, with a doctor's note","Work, with a note from your employer"],h:"Exceptions need a signed note for a real need.",e:"Valid exceptions include medical, school, work, or family needs, with signed notes. Social trips aren't exceptions."},

// ---------- FREEWAYS ----------
{t:"freeway",s:"merge",q:"When entering a freeway, you should:",a:["Speed up on the ramp to match freeway traffic","Stop at the end of the on-ramp","Enter slowly and let traffic go around you"],h:"Merge at the speed of traffic.",e:"Use the ramp to speed up, signal, and merge into a gap at traffic speed."},
{t:"freeway",q:"You missed your freeway exit. You should:",a:["Go on to the next exit","Back up on the shoulder","Stop and wait for a gap, then reverse"],h:"Never go backwards on a freeway.",e:"Just take the next exit and find your way back."},
{t:"freeway",q:"When leaving a freeway, you should start slowing down:",a:["Once you're in the exit lane","While still in the fast lane","Before you signal"],h:"Keep up with traffic until you're off.",e:"Signal, move into the exit lane, then slow down."},
{t:"freeway",q:"You may enter or exit a carpool (HOV) lane:",a:["Only where the lines are broken","Anywhere, as long as you signal","By driving across the shoulder"],h:"Look for the dashed openings.",e:"Crossing double solid lines into or out of a carpool lane is illegal."},
{t:"freeway",q:"Carpool (HOV) lane signs tell you:",a:["How many people must be in the car, and when","The speed limit for trucks","Where the next exit is"],h:"2+ or 3+?",e:"Signs show the minimum number of people per vehicle and the hours the carpool rules apply."},
{t:"freeway",q:"A ramp meter (signal on the on-ramp) turns green. Usually:",a:["One car goes per green light","Everyone in line goes","Two cars go per green light"],h:"It's metering — one at a time.",e:"Ramp meters let one vehicle go per green unless a sign says otherwise."},
{t:"freeway",q:"Your car breaks down on the freeway. You should:",a:["Get completely off the road and turn on your hazards","Stop in your lane and wait for help","Walk across the freeway for help"],h:"Get out of the traffic lanes.",e:"Pull fully onto the shoulder, use your hazard lights, and stay away from traffic."},
{t:"freeway",q:"Your lane is ending and traffic must merge. The best way is to:",a:["Take turns smoothly, like a zipper","Speed up and cut in at the last second","Stop and wait for a big gap"],h:"Fair and smooth.",e:"Zipper merging — alternating one car at a time — keeps traffic flowing safely."},
{t:"freeway",q:"On a freeway with several lanes, the far-left lane is mainly for:",a:["Passing and faster traffic","Slow vehicles","Trucks towing trailers"],h:"Slower traffic keeps right.",e:"Use the left lane to pass, then move back right."},
{t:"freeway",q:"You pass a crash on the other side of the freeway. You should:",a:["Keep your eyes on the road and keep moving","Slow down to get a look","Stop and take photos"],h:"Rubbernecking causes more crashes.",e:"Slowing to look ('rubbernecking') causes more collisions."},
{t:"freeway",q:"On a long, boring freeway drive, to avoid 'highway hypnosis' you should:",a:["Keep your eyes moving and take breaks","Stare at the car ahead","Set cruise control and relax"],h:"Stay actively scanning.",e:"Scan mirrors and the road, and take breaks every couple of hours."},

// ---------- RAILROADS & SCHOOL BUSES ----------
{t:"rail",s:"crossbuck",q:"Railroad crossing lights are flashing. You must stop:",a:["Between 15 and 50 feet from the nearest rail","Right next to the first rail","At least 100 feet from the rail"],h:"'15 to 50 — that's nifty.'",e:"Stop 15–50 feet from the nearest rail and wait until it's safe."},
{t:"rail",q:"Traffic is backed up across a railroad crossing. You should:",a:["Wait before the tracks until there's room on the other side","Stop on the tracks — traffic will move soon","Drive around the stopped cars"],h:"Never get trapped on tracks.",e:"Don't enter the crossing unless you can fully clear the tracks."},
{t:"rail",q:"Your car stalls on the tracks and a train is coming. You should:",a:["Get out and run toward the train at an angle","Stay inside and keep trying to restart","Run along the tracks away from the train"],h:"Debris flies forward in the train's direction.",e:"Get everyone out now. Run toward the train at an angle, away from the tracks, so flying debris doesn't hit you. Then call the number on the crossing sign or 911."},
{t:"rail",q:"The crossing gates are down, but you don't see a train. You should:",a:["Wait until the gates go up","Drive around them if no train is in sight","Honk and drive through slowly"],h:"Gates are not a suggestion.",e:"Never drive around lowered gates. Trains are closer and faster than they look."},
{t:"rail",q:"A train has just passed, but the crossing lights keep flashing. You should:",a:["Keep waiting — another train may be coming","Go — the train has passed","Drive around the gate"],h:"There may be more than one track.",e:"A second train can be hidden behind the first. Wait until the lights stop and you can see clearly both ways."},
{t:"rail",q:"A sign below the railroad crossbuck says '2 TRACKS.' This means:",a:["More than one train could be coming","There are two crossings ahead","You must wait two minutes"],h:"After one train passes, look again.",e:"Wait for a clear view in both directions — a second train could be hidden behind the first."},
{t:"rail",q:"How long can it take a fast train to stop?",a:["A mile or more","About 100 feet","About the same as a car"],h:"Trains weigh thousands of tons.",e:"A fast train can need a mile or more to stop. It can't stop for you."},
{t:"rail",s:"bus",q:"A school bus ahead is stopped with flashing RED lights. You must:",a:["Stop and stay stopped until the lights stop flashing","Pass slowly and carefully","Stop, then go if no children are in sight"],h:"Red = stop and wait.",e:"Stop (from either direction) and wait until the red lights turn off — kids may be crossing."},
{t:"rail",q:"A school bus ahead has flashing YELLOW lights. This means:",a:["Get ready to stop — it's about to load or unload","Speed up and pass before it stops","Nothing — only red lights matter"],h:"Yellow comes before red.",e:"Flashing yellow warns that the bus is about to stop and turn on its red lights."},
{t:"rail",q:"You don't have to stop for a school bus with flashing red lights when:",a:["It's on the other side of a divided or multilane highway","No children are in sight","You're running late"],h:"The road layout matters.",e:"Only traffic on the other side of a divided highway, or a road with 2+ lanes each way, may keep going (carefully)."},
{t:"rail",q:"Illegally passing a stopped school bus can cost you:",a:["Up to $1,000 and a 1-year suspension","A warning only","A $25 fine"],h:"It's taken very seriously.",e:"Penalties can include a fine up to $1,000 and losing your license for a year."},
{t:"rail",q:"Which vehicles must stop at EVERY railroad crossing?",a:["Passenger buses and trucks carrying hazardous materials","All passenger cars","Motorcycles"],h:"Think about the cargo.",e:"Buses carrying passengers, school buses, and hazmat trucks must always stop. Be ready when following them."},

// ---------- EMERGENCIES & CRASHES ----------
{t:"emerg",q:"You're in a crash where someone is hurt or damage is over $1,000. You must report it to the DMV within:",a:["10 days","30 days","60 days"],h:"Ten fingers, ten days.",e:"File an SR-1 report with the DMV within 10 days, even if the crash wasn't your fault."},
{t:"emerg",q:"If someone is hurt or killed in a crash, you must report it to the police or CHP within:",a:["24 hours","72 hours","10 days"],h:"Right away — within a day.",e:"Injury or fatal crashes must be reported to the police (or CHP) within 24 hours."},
{t:"emerg",q:"You hit a parked car and can't find the owner. You must:",a:["Leave a note with your name and address, and notify police","Drive away if the damage is small","Wait one hour, then leave"],h:"Leaving with no note is hit-and-run.",e:"Leave a secure note with your information and notify the local police or CHP."},
{t:"emerg",q:"Your brakes suddenly stop working. You should:",a:["Pump the brakes, shift to a lower gear, and use the parking brake","Turn off the engine right away","Steer onto the shoulder at full speed"],h:"'Pump, Gear, Park.'",e:"Pumping may build pressure, a lower gear slows you, and the parking brake helps you stop."},
{t:"emerg",q:"A tire blows out while you're driving. You should:",a:["Hold the wheel firmly and ease off the gas","Slam on the brakes","Turn the wheel sharply"],h:"Stay calm and straight.",e:"Grip the wheel, slow down gradually, and pull off when it's safe."},
{t:"emerg",q:"Your gas pedal gets stuck. You should:",a:["Shift into neutral, brake, and pull off safely","Turn the engine off at high speed","Pump the gas pedal"],h:"Disconnect the engine from the wheels.",e:"Neutral cuts engine power to the wheels so you can brake and steer off the road."},
{t:"emerg",q:"Your right wheels drift off the pavement onto the shoulder. You should:",a:["Ease off the gas, then steer gently back when safe","Jerk the wheel back right away","Slam on the brakes"],h:"Smooth, not sudden.",e:"Sudden steering can flip or spin the car. Slow down and return gently."},
{t:"emerg",q:"A car is coming toward you in your lane. You should:",a:["Slow down, steer right, and honk","Steer left into the other lane","Speed up and flash your lights"],h:"Get out of its path to the right.",e:"Pull to the right, sound your horn, and slow down. Steering left could put you head-on if the other driver corrects."},
{t:"emerg",q:"After a collision, you must:",a:["Stop, help anyone injured, and exchange information","Leave if the damage looks small","Keep going and call your insurance later"],h:"Leaving is a crime.",e:"Stop, call 911 if anyone is hurt, and exchange names, license, insurance, and registration."},
{t:"emerg",q:"An officer signals you to pull over. You should:",a:["Pull to the right safely, stop, and keep your hands visible","Get out of the car right away","Drive to a parking lot a few miles away"],h:"Stay calm and in the car.",e:"Signal, pull to the right, turn on your interior light at night, and keep your hands where they can be seen."},
{t:"emerg",q:"When stopped by law enforcement, you must show:",a:["Your license, registration, and proof of insurance","Only your school or work ID","Nothing — it's optional"],h:"Three documents.",e:"Drivers must provide their license, registration, and proof of insurance."}
];
